  left: 13px; top: 50%;
  transform: translateY(-50%) rotate(45deg);
  width: 9px; height: 9px;
  border: 2px solid #10b981;
  border-radius: 50% 50% 50% 0;
}
.xt-text-wallet_app::before {
  content: "";
  position: absolute;
  left: 16px; top: 16px;
  width: 30px; height: 22px;
  border-radius: 4px;
  background: linear-gradient(135deg, rgba(255,255,255,0.85), rgba(255,255,255,0.3));
  box-shadow: inset 0 0 4px rgba(0,0,0,0.3);
}
.xt-text-cmt_all::before {
  content: "评论";
  display: block;
  font-size: 10px; font-weight: 700;
  letter-spacing: 2.6px;
  color: #c9a86a;
  margin-bottom: 10px;
}
.xt-quote::before {
  content: "“";
  position: absolute;
  left: 7px; top: 0;
  font-family: Georgia, serif;
  font-size: 38px; line-height: 1;
  color: #c9a86a;
  opacity: 0.55;
}
/* ===== 第17段 · 神秘网站 ===== */
.xt-text-porn_title {
  position: relative;
  padding: 16px 16px 12px;
  background: linear-gradient(160deg, #141414, #0a0a0a);
  border: 1px solid rgba(255,153,0,0.4);
  border-bottom: none;
  border-radius: 14px 14px 0 0;
  font-size: 14px; font-weight: 700;
  color: #ff9900;
  line-height: 1.6;
  margin: 0 !important;
}
.xt-text-porn_title::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 4px;
  background: linear-gradient(90deg, #ff9900, rgba(255,153,0,0.2));
  border-radius: 12px 12px 0 0;
}
.xt-text-porn_title::after {
  content: "";
  position: absolute;
  right: 16px; bottom: 10px;
  border-left: 10px solid #ff9900;
  border-top: 7px solid transparent;
  border-bottom: 7px solid transparent;
  opacity: 0.85;
}
.xt-text-porn_desc {
  padding: 12px 16px;
  background: #0e0e0e;
  border: 1px solid rgba(255,153,0,0.25);
  border-top: none;
  border-bottom: none;
  border-radius: 0;
  font-size: 13px; line-height: 2;
  color: rgba(255,255,255,0.88);
  margin: 0 !important;
}
.xt-text-porn_feel {
  padding: 10px 14px 12px;
  background: #0a0a0a;
  border: 1px solid rgba(255,153,0,0.25);
  border-top: none;
  border-radius: 0 0 14px 14px;
  font-size: 12.5px; line-height: 1.9;
  color: rgba(255,255,255,0.9);
  margin: 0 !important;
}
.xt-text-porn_feel::before {
  content: "我的感受";
  display: block;
  font-size: 10px; font-weight: 700;
  letter-spacing: 2.4px;
  color: #ff9900;
  margin-bottom: 4px;
}

